#include "nge103bpage.h"

#include <QMessageBox>

#include "channelcard.h"
#include "nge103bsession.h"
#include "ui_nge103bpage.h"   // generated by uic from nge103bpage.ui

Nge103bPage::Nge103bPage(iwp::DeviceModel *model, QWidget *parent)
    : QWidget(parent), m_model(model), ui(std::make_unique<Ui::Nge103bPage>())
{
    ui->setupUi(this);

    for (int ch = 1; ch <= Nge103bSession::kChannels; ++ch)
        ui->cardsLayout->addWidget(new ChannelCard(m_model, ch, this));

    // One button toggles the master output. With "Safe mode" checked, turning it ON
    // (voltage appears on the terminals of every armed channel) needs a confirmation;
    // OFF is always immediate.
    connect(ui->masterButton, &QPushButton::clicked, this, [this] {
        const bool on = m_model->value(QStringLiteral("master")).toBool();
        if (!on && ui->safeCheck->isChecked()) {
            const auto answer = QMessageBox::warning(
                this, tr("Enable master output"),
                tr("Voltage will appear on the terminals of all armed channels.\n"
                   "Check the load and the wiring. Continue?"),
                QMessageBox::Yes | QMessageBox::No, QMessageBox::No);
            if (answer != QMessageBox::Yes)
                return;
        }
        m_model->sendCommand(QStringLiteral("master"), !on);
    });

    connect(m_model, &iwp::DeviceModel::valueChanged, this,
            [this](const QString &key, const QVariant &) { refresh(key); });
    connect(m_model, &iwp::DeviceModel::statusChanged, this, &Nge103bPage::showStatus);

    for (const QString &key : m_model->keys())
        refresh(key);
    refresh(QStringLiteral("master"));
    showStatus(m_model->status(), m_model->statusMessage());
}

Nge103bPage::~Nge103bPage() = default;   // here Ui::Nge103bPage is a complete type

void Nge103bPage::refresh(const QString &key)
{
    if (key == QLatin1String("idn")) {
        ui->idnLabel->setText(m_model->value(key).toString());
    } else if (key == QLatin1String("master")) {
        const bool on = m_model->value(key).toBool();
        ui->masterButton->setText(on ? tr("Master output: ON  (click to turn off)")
                                     : tr("Master output: OFF  (click to turn on)"));
        ui->masterButton->setStyleSheet(on ? QStringLiteral("background: #f9a825; color: black;")
                                           : QString());
    }
}

void Nge103bPage::showStatus(iwp::DeviceModel::Status status, const QString &message)
{
    static const char *names[] = {QT_TR_NOOP("Stopped"), QT_TR_NOOP("Connecting"),
                                  QT_TR_NOOP("Starting"), QT_TR_NOOP("Running"),
                                  QT_TR_NOOP("Offline"), QT_TR_NOOP("Error")};
    const bool running = status == iwp::DeviceModel::Status::Running;
    ui->statusLabel->setText(tr(names[int(status)])
                             + (message.isEmpty() ? QString() : QStringLiteral(" - ") + message));
    ui->statusLabel->setStyleSheet(running ? QStringLiteral("color: #2e7d32;")
                                           : QStringLiteral("color: #c62828;"));
    ui->masterButton->setEnabled(running);
}
